actions.action:
// Physical presence but below threshold - file but no tax due
result.tx_qualifies_for_no_tax_due = true;
result.tx_franchise_tax = 0.0;
apportionment.state_tax = 0.0;

// Physical nexus established - franchise tax calculation required
// Margin calculation will be done by table 50220
result.tx_qualifies_for_no_tax_due = false;

// No nexus - no filing required
result.tx_qualifies_for_no_tax_due = true;
result.tx_franchise_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

// No nexus or below threshold - deduction method not applicable
result.tx_deduction_method = "none";
result.tx_margin_deduction = 0.0;

// 70% of revenue provides the largest deduction
result.tx_deduction_method = "70_percent";
result.tx_margin_deduction = result.tx_total_revenue * 0.70;

// COGS provides larger deduction than compensation
result.tx_deduction_method = "cogs";
result.tx_margin_deduction = result.tx_cogs;

// Compensation provides larger deduction than COGS
result.tx_deduction_method = "compensation";
result.tx_margin_deduction = result.tx_compensation;

// No nexus or below threshold - no margin calculation
result.tx_taxable_margin = 0.0;
result.tx_apportioned_margin = 0.0;

            // E-Z Computation option available (simplified calculation)
            result.tx_qualifies_for_ez_computation = true;

            // Standard margin calculation
            result.tx_taxable_margin = Math.max(0.0,
              result.tx_total_revenue - result.tx_margin_deduction);

            // Apportion to Texas using receipts factor
            result.tx_apportioned_margin =
              result.tx_taxable_margin * apportionment.apportionment_factor;

            // Standard margin calculation (E-Z Computation not available)
            result.tx_qualifies_for_ez_computation = false;

            // Calculate taxable margin
            result.tx_taxable_margin = Math.max(0.0,
              result.tx_total_revenue - result.tx_margin_deduction);

            // Apportion to Texas using single-sales factor
            // (percentage of receipts sourced to Texas)
            result.tx_apportioned_margin =
              result.tx_taxable_margin * apportionment.apportionment_factor;

// No nexus or below threshold - no franchise tax
result.tx_franchise_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // E-Z Computation (simplified method for businesses $20M or less)
            // Tax = (Revenue - $1.23M) × 0.575% × Apportionment Factor

            double taxable_revenue = Math.max(0.0,
              result.tx_total_revenue - result.tx_no_tax_due_threshold);

            result.tx_franchise_tax =
              taxable_revenue * result.tx_ez_computation_rate * apportionment.apportionment_factor;

            // Subtract credits
            result.tx_franchise_tax =
              Math.max(0.0, result.tx_franchise_tax - apportionment.state_credits);

            // Set state tax (franchise tax is the state's "tax" even though not income tax)
            apportionment.state_tax = result.tx_franchise_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // Retail/wholesale reduced rate (0.375%)
            result.tx_margin_tax_rate = 0.00375;

            result.tx_franchise_tax =
              result.tx_apportioned_margin * result.tx_margin_tax_rate;

            // Subtract credits
            result.tx_franchise_tax =
              Math.max(0.0, result.tx_franchise_tax - apportionment.state_credits);

            // Set state tax
            apportionment.state_tax = result.tx_franchise_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // Standard rate (0.75%)
            result.tx_margin_tax_rate = 0.0075;

            result.tx_franchise_tax =
              result.tx_apportioned_margin * result.tx_margin_tax_rate;

            // Subtract credits
            result.tx_franchise_tax =
              Math.max(0.0, result.tx_franchise_tax - apportionment.state_credits);

            // Set state tax
            apportionment.state_tax = result.tx_franchise_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

// No apportioned margin - no franchise tax
result.tx_franchise_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;
